-- Epic #441 (alexkulya audit rows NP003 / WU004). Staged 2026-09-23,
-- re-checked 2026-10-04 against the LoA base world dump + sql/updates and LoA SmartAI enums.
-- LoA port: Dire Wolf (entry 43704, Duskwood) - SmartAI (Rabies 3150 in combat, Enrage 18501 + emote at 50% HP)
-- and spawn cleanup (LoA had 90 spawns incl. 15 on short waypoint paths -> 62 spawns).
-- Source: alexkulya ref commit c33511a, sql/updates/world/2026_08_22_01_world_dire_wolf.sql.
-- Adaptations for LoA:
--  * creature_text / creature_text_locale blocks DROPPED: LoA already has creature_text 43704 group 0
--    ("%s goes into a frenzy!", BroadcastTextId 1191), which the "Say Text Line 0" action uses; LoA ships no ruRU
--    creature_text_locale rows.
--  * creature.movement_type -> creature.MovementType. smart_scripts: LoA-only columns event_param5/target_param4 take default 0.
--  * guids verified: all 90 LoA spawns of 43704 have the same guid+position as ak_world; every inserted guid was a 43704
--    spawn; DELETE guarded by `id` = 43704; no formation/pool/game_event/linked_respawn references.
-- Re-runnable: addon/waypoint/smart_scripts/creature rows are deleted before being inserted.

DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `id` = 43704);
DELETE FROM `waypoint_data` WHERE `id` IN (SELECT `guid` FROM `creature` WHERE `id` = 43704);
DELETE FROM `creature_template_addon` WHERE `entry` = 43704;

UPDATE `creature_template` SET `unit_flags` = 0, `AIName` = 'SmartAI', `ScriptName` = '' WHERE `entry` = 43704;

DELETE FROM `smart_scripts` WHERE `entryorguid` = 43704 AND `source_type` = 0;

DELETE FROM `creature` WHERE `guid` IN (170580, 170606, 170645, 170647, 170648, 170649, 170652, 170657, 170661, 170663, 170667, 170670, 170671, 170674,
                                        170676, 170677, 170680, 170681, 170682, 170683, 170686, 170687, 170689, 170690, 170691, 170692, 170712, 170713,
                                        170715, 170718, 170725, 170726, 170742, 170746, 170747, 170748, 170749, 170750, 170764, 170885, 171447, 171477,
                                        171478, 171479, 171480, 171530, 171574, 179228, 179231, 179234, 179422, 179443, 179466, 179591, 179608, 179628,
                                        179629, 179702, 179802, 179810, 179839, 180319, 180331, 180345, 180346, 180379, 180382, 180424, 180433, 180439,
                                        180467, 180468, 180550, 180551, 180553, 180556, 180577, 184669, 185050, 185064, 185065, 185066, 185067, 185639,
                                        185641, 185645, 185647, 185653, 185654, 185658) AND `id` = 43704;
